import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useSelector, useDispatch } from 'react-redux';
import { logout } from '../../redux/slices/authSlice';
import { showPopup } from '../../redux/slices/popupSlice';

const Navbar = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const { isAuthenticated, user } = useSelector(state => state.auth);
  const dispatch = useDispatch();
  const navigate = useNavigate();

  const handleLogout = async () => {
    try {
      await dispatch(logout()).unwrap();
      dispatch(showPopup({
        message: 'Logged out successfully!',
        type: 'success'
      }));
      navigate('/');
    } catch (error) {
      dispatch(showPopup({
        message: 'Logout failed!',
        type: 'error'
      }));
    }
  };

  return (
    <nav className="navbar">
      <div className="container">
        <div className="navbar-content">
          <Link to="/" className="nav-brand">
            RYDO
          </Link>

          <ul className="nav-links">
            <li><Link to="/booking" className="nav-link">Booking</Link></li>
            <li><Link to="/drivers" className="nav-link">Drivers</Link></li>
            <li className="dropdown">
              <span className="nav-link">Company</span>
            </li>
          </ul>

          <div className="nav-actions">
            {!isAuthenticated ? (
              <>
                <Link to="/login" className="btn btn-secondary btn-sm">
                  Sign In
                </Link>
                <Link to="/register" className="btn btn-primary btn-sm">
                  Sign Up
                </Link>
              </>
            ) : (
              <div className="user-menu">
                <span className="nav-link">
                  <i className="fas fa-user"></i> {user?.name}
                </span>
                <div className="dropdown-menu">
                  <Link to="/dashboard" className="dropdown-item">Dashboard</Link>
                  <Link to="/booking-history" className="dropdown-item">My Rides</Link>
                  {user?.role === 'driver' && (
                    <Link to="/driver-dashboard" className="dropdown-item">Driver Dashboard</Link>
                  )}
                  {user?.role === 'admin' && (
                    <Link to="/admin-dashboard" className="dropdown-item">Admin Dashboard</Link>
                  )}
                  <button onClick={handleLogout} className="dropdown-item">Logout</button>
                </div>
              </div>
            )}
            
            <span className="nav-link">
              <i className="fas fa-map-marker-alt"></i>
            </span>
          </div>

          <button 
            className="mobile-menu-btn"
            onClick={() => setIsMenuOpen(!isMenuOpen)}
          >
            <i className={`fas ${isMenuOpen ? 'fa-times' : 'fa-bars'}`}></i>
          </button>
        </div>

        {/* Mobile Menu */}
        {isMenuOpen && (
          <div className="mobile-menu">
            <Link to="/booking" className="mobile-nav-link">Booking</Link>
            <Link to="/drivers" className="mobile-nav-link">Drivers</Link>
            <Link to="/company" className="mobile-nav-link">Company</Link>
            
            {isAuthenticated ? (
              <>
                <Link to="/dashboard" className="mobile-nav-link">Dashboard</Link>
                <button onClick={handleLogout} className="mobile-nav-link">Logout</button>
              </>
            ) : (
              <>
                <Link to="/login" className="mobile-nav-link">Sign In</Link>
                <Link to="/register" className="mobile-nav-link">Sign Up</Link>
              </>
            )}
          </div>
        )}
      </div>

      <style jsx>{`
        .dropdown {
          position: relative;
        }
        
        .dropdown-menu {
          position: absolute;
          top: 100%;
          left: 0;
          background: white;
          border-radius: var(--border-radius);
          box-shadow: var(--shadow-lg);
          padding: 0.5rem 0;
          min-width: 200px;
          display: none;
        }
        
        .dropdown:hover .dropdown-menu {
          display: block;
        }
        
        .dropdown-item {
          display: block;
          padding: 0.75rem 1rem;
          color: var(--text-dark);
          text-decoration: none;
          border: none;
          background: none;
          width: 100%;
          text-align: left;
          cursor: pointer;
        }
        
        .dropdown-item:hover {
          background: var(--bg-light);
        }
        
        .mobile-menu-btn {
          display: none;
          background: none;
          border: none;
          color: white;
          font-size: 1.5rem;
          cursor: pointer;
        }
        
        .mobile-menu {
          display: none;
          flex-direction: column;
          gap: 1rem;
          margin-top: 1rem;
          padding-top: 1rem;
          border-top: 1px solid rgba(255, 255, 255, 0.2);
        }
        
        .mobile-nav-link {
          color: white;
          text-decoration: none;
          padding: 0.5rem 0;
        }
        
        @media (max-width: 768px) {
          .nav-links {
            display: none;
          }
          
          .mobile-menu-btn {
            display: block;
          }
          
          .mobile-menu {
            display: flex;
          }
        }
      `}</style>
    </nav>
  );
};

export default Navbar;
